-- Paket ABT "abt-murtad-8529-30okt": satu transaksi; hanya 8529, hanya bila isinya persis sebelum paket. Isi baru = hex latin1 (nama basis dipasang).
START TRANSACTION;
UPDATE abt_variabel SET sql_query = REPLACE(CONVERT( USING latin1), 'aps_badilag.', CONCAT(DATABASE(), '.'))
 WHERE no_var = 8529 AND MD5(REPLACE(sql_query, CONCAT(DATABASE(), '.'), 'aps_badilag.')) = '7d03edaa4ddf9c305703328b8e04135b';
COMMIT;
